"use client";

import { useEffect, useRef, useState, type FormEvent, type ReactNode } from "react";
import * as Dialog from "@radix-ui/react-dialog";
import { RiArrowLeftSLine, RiArrowRightSLine, RiArrowDownSLine, RiArrowRightUpLine, RiCalendar2Line, RiDashboardLine, RiGroupLine, RiTimeLine, RiSettings3Line, RiNotification3Line, RiSearchLine, RiAddLine, RiCheckLine, RiCloseLine, RiSparkling2Line, RiShareForwardLine, RiDownloadLine, RiMoreLine, RiArrowGoBackLine, RiArrowGoForwardLine, RiLockLine, RiSunLine, RiMoonLine, RiCheckboxCircleLine, RiErrorWarningLine, RiHistoryLine, RiMenuLine, RiLogoutBoxRLine, RiCupLine, RiFileCopyLine, RiDeleteBinLine, RiRefreshLine, RiExternalLinkLine, RiInformationLine, RiLayoutGridLine, RiListCheck } from "@remixicon/react";
import { Button } from "@/components/ui/button";
import { createDemo } from "@/lib/demo";
import { addDays, assignmentConflicts, DAY_NAMES, duration, generateSchedule, hoursFor, missingRequirements, monday, neighborAssignments, validateSchedule, weekDates, type Assignment, type Employee, type Position, type Schedule, type Workspace } from "@/lib/scheduler";
import { applyChange, readState, redoState, STORAGE_KEY, undoState, writeState, type StoredState } from "@/lib/storage";
import { getSupabase, loadCloud, saveCloud, createShare, loadShared } from "@/lib/supabase";

type Page = "Raspored" | "Pregled" | "Zaposleni" | "Dostupnost" | "Pravila rada" | "Istorija izmena" | "Podešavanja";
type Modal = "generate" | "employee" | "shift" | "publish" | "share" | "export" | "auth" | "notifications" | null;
const nav = [{ name: "Pregled", icon: RiDashboardLine }, { name: "Raspored", icon: RiCalendar2Line }, { name: "Zaposleni", icon: RiGroupLine }, { name: "Dostupnost", icon: RiTimeLine }, { name: "Pravila rada", icon: RiListCheck }] as const;
const positions: Position[] = ["Barista", "Konobar", "Menadžer"];
const dateLabel = (date: Date, opts: Intl.DateTimeFormatOptions) => date.toLocaleDateString("sr-Latn-RS", { ...opts, timeZone: "Europe/Belgrade" });
const iconSize = 17;

function ModalFrame({ title, description, children, close }: { title: string; description?: string; children: ReactNode; close: () => void }) {
  return <Dialog.Root open onOpenChange={open => { if (!open) close(); }}><Dialog.Portal><Dialog.Overlay className="modal-overlay" /><Dialog.Content className="modal-content"><div className="modal-heading"><div><Dialog.Title>{title}</Dialog.Title>{description && <Dialog.Description>{description}</Dialog.Description>}</div><Dialog.Close className="icon-button" aria-label="Zatvori"><RiCloseLine size={20} /></Dialog.Close></div>{children}</Dialog.Content></Dialog.Portal></Dialog.Root>;
}
function Avatar({ employee, small = false }: { employee: Employee; small?: boolean }) { return <span className={`avatar ${employee.color} ${small ? "small" : ""}`}>{employee.initials}</span>; }
function Empty({ children }: { children: ReactNode }) { return <div className="empty"><RiCalendar2Line size={32} /><p>{children}</p></div>; }

export default function ShiftFlow() {
  const [state, setState] = useState<StoredState | null>(null);
  const [page, setPage] = useState<Page>("Raspored");
  const [week, setWeek] = useState(monday());
  const [view, setView] = useState("week");
  const [day, setDay] = useState(0);
  const [query, setQuery] = useState("");
  const [position, setPosition] = useState("all");
  const [modal, setModal] = useState<Modal>(null);
  const [toast, setToast] = useState("");
  const [saveStatus, setSaveStatus] = useState("Sačuvano lokalno");
  const [saveError, setSaveError] = useState(false);
  const [sidebar, setSidebar] = useState(false);
  const [keepLocked, setKeepLocked] = useState(true);
  const [busy, setBusy] = useState(false);
  const [editEmployee, setEditEmployee] = useState<Employee | null>(null);
  const [editShift, setEditShift] = useState<Partial<Assignment> | null>(null);
  const [formError, setFormError] = useState("");
  const [cloudId, setCloudId] = useState<string | null>(null);
  const [cloudVersion, setCloudVersion] = useState(0);
  const [authUser, setAuthUser] = useState("");
  const [shareUrl, setShareUrl] = useState("");
  const [shared, setShared] = useState<{ name: string; schedule: Schedule; employees: { id: string; name: string }[]; templates: Workspace["templates"] } | null>(null);
  const [sharedError, setSharedError] = useState("");
  const [shareToken, setShareToken] = useState<string | null>(null);
  const [theme, setTheme] = useState("dark");
  const [showProblems, setShowProblems] = useState(false);
  const [more, setMore] = useState(false);
  const calendarRef = useRef<HTMLDivElement>(null);
  const latest = useRef<StoredState | null>(null);
  const cloudRevision = useRef(-1);
  const cloudInFlight = useRef(false);
  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const notify = (message: string) => { setToast(message); if (toastTimer.current) clearTimeout(toastTimer.current); toastTimer.current = setTimeout(() => setToast(""), 4500); };

  useEffect(() => {
    try {
      const saved = readState();
      const initial: StoredState = saved ?? { schema: 1, revision: 0, current: createDemo(), past: [], future: [] };
      setState(initial); latest.current = initial;
      setView(localStorage.getItem("shiftflow:view") || "week");
      setTheme(localStorage.getItem("shiftflow:theme") || "dark");
    } catch { setSaveStatus("Nije moguće učitati lokalne podatke"); setSaveError(true); setState({ schema: 1, revision: 0, current: createDemo(), past: [], future: [] }); }
    const token = new URLSearchParams(location.search).get("share");
    if (token) { setShareToken(token); loadShared(token).then(setShared).catch(e => setSharedError(e.message)); }
    const supabase = getSupabase();
    if (supabase && !token) {
      const connect = async () => { const { data } = await supabase.auth.getSession(); if (data.session) { setAuthUser(data.session.user.email || ""); try { const cloud = await loadCloud(); if (cloud) { const key = `shiftflow:company:${cloud.company_id}:v1`; const previous = localStorage.getItem(key); if (previous && previous !== JSON.stringify(cloud.state)) localStorage.setItem(`${key}:recovery`, previous); const next = cloud.state as StoredState; setCloudId(cloud.company_id); setCloudVersion(cloud.version); cloudRevision.current = next.revision; setState(next); latest.current = next; setSaveStatus("Sinhronizovano"); } } catch (e) { notify((e as Error).message); } } };
      void connect();
    }
    const onStorage = (event: StorageEvent) => { if (event.key !== STORAGE_KEY || !event.newValue) return; try { const incoming = JSON.parse(event.newValue) as StoredState; if (incoming.revision >= (latest.current?.revision ?? 0)) { setState(incoming); latest.current = incoming; notify("Učitana je novija izmena iz drugog prozora."); } } catch { /* Ignore unrelated malformed events. */ } };
    window.addEventListener("storage", onStorage); return () => window.removeEventListener("storage", onStorage);
  }, []);

  useEffect(() => { document.documentElement.dataset.theme = theme; }, [theme]);
  useEffect(() => {
    if (!state) return; latest.current = state;
    try { writeState(state, cloudId ? `shiftflow:company:${cloudId}:v1` : STORAGE_KEY); setSaveError(false); setSaveStatus(cloudId ? "Sinhronizovano" : "Sačuvano lokalno"); }
    catch { setSaveError(true); setSaveStatus("Čuvanje nije uspelo"); return; }
    if (!cloudId || state.revision === cloudRevision.current) return;
    setSaveStatus("Čuvanje…");
    const controller = setTimeout(() => { if (cloudInFlight.current) return; cloudInFlight.current = true; void saveCloud(cloudId, state, cloudVersion).then(version => { cloudRevision.current = state.revision; setCloudVersion(version); setSaveStatus("Sinhronizovano"); }).catch(e => { setSaveError(true); setSaveStatus("Pokušaj ponovo"); notify((e as Error).message); }).finally(() => { cloudInFlight.current = false; }); }, 650);
    return () => clearTimeout(controller);
  }, [state, cloudId, cloudVersion]);

  const commit = (next: Workspace, label: string) => setState(s => s ? applyChange(s, next, label) : s);
  const undo = () => setState(s => s ? undoState(s) : s);
  const redo = () => setState(s => s ? redoState(s) : s);
  useEffect(() => {
    const handler = (event: KeyboardEvent) => { if ((event.target as HTMLElement).matches("input, textarea, select")) return; if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "z") { event.preventDefault(); if (event.shiftKey) redo(); else undo(); } if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "y") { event.preventDefault(); redo(); } };
    window.addEventListener("keydown", handler); return () => window.removeEventListener("keydown", handler);
  }, []);

  if (shareToken) {
    return <main className="shared-page"><div className="brand"><span className="brand-icon">s<span>f</span></span>ShiftFlow</div>{sharedError ? <Empty>{sharedError}</Empty> : !shared ? <Empty>Učitavanje objavljenog rasporeda…</Empty> : <><p className="eyebrow">RASPORED TIMA</p><h1>{shared.name}</h1><p className="muted">Nedelja od {dateLabel(new Date(shared.schedule.week + "T12:00:00Z"), { day: "numeric", month: "long", year: "numeric" })}</p><div className="shared-list">{DAY_NAMES.map((name, i) => <section key={name}><h3>{name}</h3>{shared.schedule.assignments.filter(a => a.day === i).map(a => { const t = shared.templates.find(t => t.id === a.templateId)!; return <div key={a.id} className="shared-shift"><span>{shared.employees.find(e => e.id === a.employeeId)?.name}</span><span className="muted">{a.position}</span><span>{t.start}–{t.end}</span></div>; })}</section>)}</div></>}<footer>ShiftFlow · Vreme je prikazano za Europe/Belgrade</footer></main>;
  }
  if (!state) return <div className="loading"><span className="brand-icon">sf</span><span>Pripremamo vaš radni prostor…</span></div>;
  const w = state.current;
  const schedule: Schedule = w.schedules[week] ?? { week, status: "draft", assignments: [] };
  const dates = weekDates(week);
  const active = w.employees.filter(e => e.active);
  const filtered = active.filter(e => e.name.toLowerCase().includes(query.toLowerCase()) && (position === "all" || e.positions.includes(position as Position)));
  const missing = missingRequirements(schedule.assignments, w.requirements);
  const missingCount = missing.reduce((n, r) => n + r.missing, 0);
  const conflicts = validateSchedule(schedule, w);
  const blockers = conflicts.filter(c => c.severity === "block");
  const required = w.requirements.reduce((n, r) => n + r.count, 0);
  const coverage = required ? Math.round((required - missingCount) / required * 100) : 100;
  const totalHours = schedule.assignments.reduce((sum, a) => sum + duration(w.templates.find(t => t.id === a.templateId)!), 0);
  const updateSchedule = (next: Schedule, label: string) => commit({ ...w, schedules: { ...w.schedules, [week]: next } }, label);
  const openShift = (employeeId?: string, dayIndex = day, assignment?: Assignment) => { setEditShift(assignment ?? { employeeId: employeeId ?? active[0]?.id, day: dayIndex, templateId: w.templates[0]?.id, position: active.find(e => e.id === employeeId)?.positions[0] ?? active[0]?.positions[0], locked: false, note: "" }); setFormError(""); setModal("shift"); };
  const setPageAndClose = (p: Page) => { setPage(p); setSidebar(false); setQuery(""); };
  const saveAssignment = (a: Assignment) => {
    const next = schedule.assignments.filter(b => b.id !== a.id);
    const issues = assignmentConflicts(a, next, w, neighborAssignments(w, week));
    if (issues.some(c => c.severity === "block")) { setFormError(issues.filter(c => c.severity === "block").map(c => c.message).join(" ")); return false; }
    updateSchedule({ ...schedule, assignments: [...next, a] }, "Izmena smene");
    if (issues.length) notify(issues[0].message); return true;
  };
  const saveShift = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const a: Assignment = { id: editShift?.id ?? crypto.randomUUID(), employeeId: String(f.get("employeeId")), day: Number(f.get("day")), templateId: String(f.get("templateId")), position: String(f.get("position")) as Position, locked: f.get("locked") === "on", note: String(f.get("note") || "") }; if (saveAssignment(a)) setModal(null); };
  const saveEmployee = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const f = new FormData(event.currentTarget); const selected = f.getAll("positions") as Position[];
    if (!selected.length) { setFormError("Izaberite bar jednu poziciju."); return; }
    const name = String(f.get("name")).trim();
    const employee: Employee = { id: editEmployee?.id ?? crypto.randomUUID(), name, initials: name.split(/\s+/).slice(0, 2).map(n => n[0]).join(""), positions: selected, targetHours: Number(f.get("hours")), color: editEmployee?.color ?? "mint", active: f.get("active") === "on", daysOff: editEmployee?.daysOff ?? [], preferredShift: String(f.get("preferred")) || undefined };
    const updated = { ...w, employees: editEmployee ? w.employees.map(e => e.id === employee.id ? employee : e) : [...w.employees, employee] };
    commit(updated, editEmployee ? `Izmena zaposlenog: ${name}` : `Dodat zaposleni: ${name}`); setModal(null); notify("Podaci zaposlenog su sačuvani.");
  };
  const duplicateWeek = () => { const target = addDays(week, 7); const previous = w.schedules[target]; if (previous?.assignments.length) { notify("Sledeća nedelja već ima smene. Izaberite praznu nedelju za kopiranje."); return; } commit({ ...w, schedules: { ...w.schedules, [target]: { week: target, status: "draft", assignments: schedule.assignments.map(a => ({ ...a, id: crypto.randomUUID() })) } } }, "Kopirana nedelja"); setWeek(target); setMore(false); notify("Raspored je kopiran u sledeću nedelju."); };
  const exportImage = async () => { if (!calendarRef.current) return; setBusy(true); try { const { toPng } = await import("html-to-image"); const node = calendarRef.current; const uri = await toPng(node, { backgroundColor: theme === "dark" ? "#111313" : "#ffffff", pixelRatio: 2, width: node.scrollWidth, height: node.scrollHeight, style: { overflow: "visible", maxHeight: "none" } }); const a = document.createElement("a"); a.download = `ShiftFlow-${week}.png`; a.href = uri; a.click(); setModal(null); } catch { notify("Izvoz slike nije uspeo. Pokušajte PDF izvoz."); } finally { setBusy(false); } };

  const ShiftChip = ({ a }: { a: Assignment }) => { const t = w.templates.find(t => t.id === a.templateId)!; const hasConflict = conflicts.some(c => c.employeeId === a.employeeId && c.day === a.day); return <button draggable onDragStart={e => { e.dataTransfer.setData("application/shiftflow", a.id); e.dataTransfer.effectAllowed = "move"; }} className={`shift-chip ${t.color} ${hasConflict ? "conflicted" : ""}`} onClick={() => openShift(a.employeeId, a.day, a)} aria-label={`${w.employees.find(e => e.id === a.employeeId)?.name}, ${DAY_NAMES[a.day]}, ${t.name}, ${t.start} do ${t.end}. Uredi smenu.`}><span className="shift-time">{t.start}<span className="time-divider">–</span>{t.end}{a.locked && <RiLockLine size={11} />}</span><span className="shift-role"><i />{a.position}{a.note && <span title={a.note}> ·</span>}</span></button>; };

  const Calendar = () => <div className="calendar-scroll" ref={calendarRef}><div className="print-heading">{w.name} · Raspored smena · {week}</div><table className="schedule-table"><thead><tr><th className="employee-col"><span>ZAPOSLENI</span><span className="head-count">{filtered.length}</span></th>{dates.map((date, i) => { const today = new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Belgrade" }).format(new Date()) === addDays(week, i); return <th key={i} className={`${i >= 5 ? "weekend" : ""} ${today ? "today" : ""}`}><span className="day-name">{DAY_NAMES[i].slice(0, 3).toUpperCase()}</span><span className="day-number">{date.getUTCDate()} <small>{dateLabel(date, { month: "short" }).replace(".", "")}</small>{today && <i />}</span></th>; })}<th className="total-col">UKUPNO</th></tr></thead><tbody>{filtered.map(employee => { const hours = hoursFor(schedule.assignments, employee.id, w.templates); return <tr key={employee.id}><th scope="row"><button className="employee-label" onClick={() => { setEditEmployee(employee); setFormError(""); setModal("employee"); }}><Avatar employee={employee} /><span><strong>{employee.name}</strong><small>{employee.positions.join(" · ")}</small></span></button></th>{DAY_NAMES.map((_, i) => { const assignments = schedule.assignments.filter(a => a.employeeId === employee.id && a.day === i); return <td key={i} className={`${i >= 5 ? "weekend" : ""} ${employee.daysOff.includes(i) ? "off-cell" : ""}`} onDragOver={e => { e.preventDefault(); e.currentTarget.classList.add("drag-over"); }} onDragLeave={e => e.currentTarget.classList.remove("drag-over")} onDrop={e => { e.preventDefault(); e.currentTarget.classList.remove("drag-over"); const source = schedule.assignments.find(a => a.id === e.dataTransfer.getData("application/shiftflow")); if (!source) return; if (source.locked) { notify("Otključajte smenu pre premeštanja."); return; } const changed = { ...source, employeeId: employee.id, day: i }; if (!saveAssignment(changed)) notify("Premeštanje nije dozvoljeno: proverite dostupnost, poziciju i odmor."); }}>{assignments.length ? assignments.map(a => <ShiftChip key={a.id} a={a} />) : employee.daysOff.includes(i) ? <button className="off-day" onClick={() => { setPage("Dostupnost"); }}>Nedostupan</button> : <button className="empty-cell" onClick={() => openShift(employee.id, i)} aria-label={`Dodaj smenu: ${employee.name}, ${DAY_NAMES[i]}`}><span>Slobodno</span><RiAddLine size={17} /></button>}</td>; })}<td className="hours-cell"><strong className={hours > w.rules.maxWeeklyHours ? "danger-text" : ""}>{hours}<small> h</small></strong><div className="hours-track"><i style={{ width: `${Math.min(100, hours / employee.targetHours * 100)}%` }} /></div><small>/ {employee.targetHours} h</small></td></tr>; })}</tbody><tfoot><tr><th>Pokrivenost smena</th>{DAY_NAMES.map((_, i) => { const gap = missing.filter(r => r.day === i).reduce((s, r) => s + r.missing, 0); const count = schedule.assignments.filter(a => a.day === i).length; return <td key={i} className={gap ? "danger-text" : ""}>{gap ? <RiErrorWarningLine size={13} /> : <RiCheckLine size={13} />}<span>{count} / {w.requirements.filter(r => r.day === i).reduce((s, r) => s + r.count, 0)}</span></td>; })}<td className="hours-cell">{totalHours} h</td></tr></tfoot></table>{!filtered.length && <Empty>Nema zaposlenih koji odgovaraju pretrazi.</Empty>}</div>;

  return <div className="app-shell">
    {sidebar && <button className="sidebar-backdrop" onClick={() => setSidebar(false)} aria-label="Zatvori navigaciju" />}
    <aside className={`sidebar ${sidebar ? "is-open" : ""}`}><a className="brand" href="#" onClick={e => { e.preventDefault(); setPageAndClose("Raspored"); }}><span className="brand-icon"><RiArrowGoForwardLine size={21} /></span>ShiftFlow<span className="brand-dot">®</span></a><button className="workspace-selector" onClick={() => setPageAndClose("Podešavanja")}><span className="workspace-symbol"><RiCupLine size={19} /></span><span><strong>{w.name}</strong><small>{cloudId ? "Poslovni prostor" : "Demo radni prostor"}</small></span><RiArrowDownSLine size={15} /></button><div className="nav-caption">RADNI PROSTOR</div><nav>{nav.map(n => <button key={n.name} className={`nav-link ${page === n.name ? "active" : ""}`} onClick={() => setPageAndClose(n.name)}><n.icon size={19} /><span>{n.name}</span>{n.name === "Zaposleni" && <small>{active.length}</small>}{n.name === "Raspored" && page === "Raspored" && <i />}</button>)}</nav><div className="sidebar-secondary"><div className="nav-caption">UPRAVLJANJE</div><button className={`nav-link ${page === "Istorija izmena" ? "active" : ""}`} onClick={() => setPageAndClose("Istorija izmena")}><RiHistoryLine size={19} />Istorija izmena</button><button className={`nav-link ${page === "Podešavanja" ? "active" : ""}`} onClick={() => setPageAndClose("Podešavanja")}><RiSettings3Line size={19} />Podešavanja</button></div><div className="sidebar-bottom"><div className="sidebar-note"><span className="note-icon"><RiSparkling2Line size={16} /></span><strong>Više vremena za dobru kafu.</strong><p>Plan za ceo tim, u nekoliko klikova.</p><button onClick={() => { setPageAndClose("Raspored"); setModal("generate"); }}>Napravi raspored <RiArrowRightUpLine size={15} /></button></div><button className="user-profile" onClick={() => setModal("auth")}><span className="avatar profile-avatar">{authUser ? authUser.slice(0, 2).toUpperCase() : "NK"}</span><span><strong>{authUser || "Nikola"}</strong><small>{cloudId ? "Vlasnik" : "Demo menadžer"}</small></span><RiMoreLine size={17} /></button></div></aside>
    <div className="main-shell"><header className="topbar"><button className="icon-button mobile-menu" aria-label="Otvori navigaciju" onClick={() => setSidebar(true)}><RiMenuLine size={21} /></button><div className="breadcrumb"><RiCupLine size={16} /><span>{w.name}</span><span className="slash">/</span><strong>{page === "Raspored" ? "Raspored smena" : page}</strong></div><div className="topbar-right"><span className="demo-badge"><i />{cloudId ? "Povezano" : "Demo prostor"}</span><div className="topbar-separator" /><button className="icon-button" title="Promeni temu" aria-label="Promeni temu" onClick={() => { const next = theme === "dark" ? "light" : "dark"; setTheme(next); localStorage.setItem("shiftflow:theme", next); }}>{theme === "dark" ? <RiSunLine size={18} /> : <RiMoonLine size={18} />}</button><button className="icon-button notification-button" aria-label="Obaveštenja" onClick={() => setModal("notifications")}><RiNotification3Line size={19} />{missingCount > 0 && <i />}</button><span className="avatar small profile-avatar">NK</span></div></header>
      <main className="main-content"><div className="page-heading"><div><div className="eyebrow">VAŠ TIM. DOBAR RITAM.</div><h1>{page === "Raspored" ? "Raspored smena" : page === "Pregled" ? "Sve na jednom mestu." : page}</h1><p>{page === "Raspored" ? "Manje planiranja. Više vremena za ono što je važno." : page === "Zaposleni" ? "Ljudi koji čine vaš tim. Sve informacije na jednom mestu." : page === "Dostupnost" ? "Uskladite raspored sa planovima svog tima." : page === "Pravila rada" ? "Vaša pravila, dosledno primenjena na svaku smenu." : page === "Istorija izmena" ? "Svaka promena je zabeležena. Vratite se korak unazad kad god zatreba." : page === "Podešavanja" ? "Radni prostor prilagođen vašem kafiću." : "Pregled tima, planiranih sati i svega što traži vašu pažnju."}</p></div><div className="heading-actions">{page === "Raspored" || page === "Pregled" ? <><Button variant="outline" onClick={() => setModal("share")}><RiShareForwardLine size={16} /> Podeli raspored</Button><Button onClick={() => { setModal("generate"); setFormError(""); }}><RiSparkling2Line size={16} /> Generiši raspored</Button></> : page === "Zaposleni" ? <Button onClick={() => { setEditEmployee(null); setFormError(""); setModal("employee"); }}><RiAddLine size={17} /> Dodaj zaposlenog</Button> : null}</div></div>

      {(page === "Raspored" || page === "Pregled") && <><div className="stats-grid"><div className="stat-card"><div><span>Aktivni zaposleni</span><RiGroupLine size={17} /></div><strong>{active.length}<small>članova tima</small></strong><p><span className="stat-dot green" />Tim spreman za novu nedelju</p></div><div className="stat-card"><div><span>Planirani sati</span><RiTimeLine size={17} /></div><strong>{totalHours}<small>h ove nedelje</small></strong><p>{schedule.assignments.length} raspoređenih smena <span className="tiny-bars">▁▃▅▃▆▅▇</span></p></div><div className="stat-card"><div><span>Pokrivenost smena</span><RiCheckboxCircleLine size={17} /></div><strong>{coverage}<small>% popunjenosti</small></strong><p><span className="coverage-track"><i style={{ width: `${coverage}%` }} /></span><span>{required - missingCount}/{required}</span></p></div><button className={`stat-card attention-card ${missingCount + conflicts.length ? "has-issues" : ""}`} onClick={() => setShowProblems(v => !v)}><div><span>Potrebna pažnja</span>{missingCount + conflicts.length ? <RiErrorWarningLine size={17} /> : <RiCheckLine size={17} />}</div><strong>{missingCount + conflicts.length}<small>{missingCount + conflicts.length ? "otvorenih stavki" : "sve je usklađeno"}</small></strong><p>{missingCount + conflicts.length ? "Pregledaj upozorenja" : "Dobar raspored. Zadovoljan tim."}<RiArrowRightUpLine size={14} /></p></button></div>{showProblems && <div className="problems-panel"><h3>Provera rasporeda</h3>{!missing.length && !conflicts.length ? <p className="success-text"><RiCheckLine size={16} />Sve smene su popunjene i pravila su ispoštovana.</p> : <><ul>{missing.map((r, i) => <li key={i}>{DAY_NAMES[r.day]}, {w.templates.find(t => t.id === r.templateId)?.name.toLowerCase()}: nedostaje {r.missing} × {r.position.toLowerCase()}.</li>)}{conflicts.map(c => <li key={c.id}>{c.message} <span className="tag">{c.severity === "block" ? "Zabrana" : "Upozorenje"}</span></li>)}</ul></>}</div>}</>}

      {page === "Raspored" && <section className="schedule-section"><div className="schedule-toolbar"><div className="week-controls"><div className="week-arrows"><button className="icon-button" aria-label="Prethodna nedelja" onClick={() => setWeek(addDays(week, -7))}><RiArrowLeftSLine size={20} /></button><button className="icon-button" aria-label="Sledeća nedelja" onClick={() => setWeek(addDays(week, 7))}><RiArrowRightSLine size={20} /></button></div><h2>{dates[0].getUTCDate()}–{dates[6].getUTCDate()}. {dateLabel(dates[6], { month: "long" })} <span>{dates[6].getUTCFullYear()}.</span></h2><button className="today-button" onClick={() => setWeek(monday())}>Danas</button><span className={`status-badge ${schedule.status === "published" ? "published" : ""}`}><i />{schedule.status === "draft" ? "Nacrt" : "Objavljeno"}</span></div><div className="view-switch" aria-label="Prikaz rasporeda">{[{ id: "week", label: "Nedelja", icon: RiCalendar2Line }, { id: "day", label: "Dan", icon: RiLayoutGridLine }, { id: "list", label: "Lista", icon: RiListCheck }].map(v => <button key={v.id} className={view === v.id ? "selected" : ""} onClick={() => { setView(v.id); localStorage.setItem("shiftflow:view", v.id); }}><v.icon size={14} />{v.label}</button>)}</div></div>
      <div className="calendar-card"><div className="calendar-filters"><div className="filter-group"><label className="search-field"><RiSearchLine size={16} /><input placeholder="Pronađi zaposlenog…" value={query} onChange={e => setQuery(e.target.value)} aria-label="Pronađi zaposlenog" /><kbd>⌕</kbd></label><div className="filter-divider" /><select className="position-select" value={position} onChange={e => setPosition(e.target.value)} aria-label="Filtriraj po poziciji"><option value="all">Sve pozicije</option>{positions.map(p => <option key={p}>{p}</option>)}</select></div><div className="calendar-tools"><button className="icon-button" title="Poništi (Ctrl+Z)" aria-label="Poništi izmenu" onClick={undo} disabled={!state.past.length}><RiArrowGoBackLine size={iconSize} /></button><button className="icon-button" title="Ponovi (Ctrl+Shift+Z)" aria-label="Ponovi izmenu" onClick={redo} disabled={!state.future.length}><RiArrowGoForwardLine size={iconSize} /></button><span className="filter-divider" /><button className="icon-button" aria-label="Preuzmi raspored" onClick={() => setModal("export")}><RiDownloadLine size={iconSize} /></button><div className="more-wrapper"><button className="icon-button" aria-label="Više opcija" aria-expanded={more} onClick={() => setMore(v => !v)}><RiMoreLine size={18} /></button>{more && <div className="dropdown-menu"><button onClick={duplicateWeek}><RiFileCopyLine size={16} />Kopiraj u sledeću nedelju</button><button onClick={() => { updateSchedule({ ...schedule, assignments: schedule.assignments.map(a => ({ ...a, locked: true })) }, "Zaključane sve smene"); setMore(false); }}><RiLockLine size={16} />Zaključaj sve smene</button><button onClick={() => { updateSchedule({ ...schedule, assignments: schedule.assignments.map(a => ({ ...a, locked: false })) }, "Otključane sve smene"); setMore(false); }}><RiRefreshLine size={16} />Otključaj sve smene</button></div>}</div><Button size="sm" variant="outline" onClick={() => openShift()}><RiAddLine size={15} />Dodaj smenu</Button></div></div>
      {view === "week" ? <Calendar /> : <div className="alternative-view">{view === "day" && <div className="day-tabs">{DAY_NAMES.map((name, i) => <button className={day === i ? "selected" : ""} key={name} onClick={() => setDay(i)}>{name.slice(0, 3)} {dates[i].getUTCDate()}.</button>)}</div>}{(view === "day" ? [day] : [0, 1, 2, 3, 4, 5, 6]).map(i => <section className="day-section" key={i}><h3>{DAY_NAMES[i]} <span>{dateLabel(dates[i], { day: "numeric", month: "long" })}</span></h3>{w.templates.map(t => <div className="day-shift-group" key={t.id}><div className={`shift-group-label ${t.color}`}>{t.id === "morning" ? <RiSunLine size={18} /> : <RiMoonLine size={18} />}<strong>{t.name}</strong><span>{t.start}–{t.end}</span></div><div>{schedule.assignments.filter(a => a.day === i && a.templateId === t.id && filtered.some(e => e.id === a.employeeId)).map(a => { const e = w.employees.find(e => e.id === a.employeeId)!; return <button key={a.id} className="day-employee" onClick={() => openShift(e.id, i, a)}><Avatar small employee={e} /><strong>{e.name}</strong><span>{a.position}</span>{a.locked && <RiLockLine size={13} />}</button>; })}<button className="day-add" onClick={() => openShift(undefined, i)}><RiAddLine size={15} />Dodaj</button></div></div>)}</section>)}</div>}
      <div className="calendar-footer"><div className="shift-legend">{w.templates.map(t => <span key={t.id}><i className={t.color} />{t.name}</span>)}<span><i className="off" />Slobodan dan</span></div><span className="save-status"><RiCheckboxCircleLine size={14} />{saveError ? <button onClick={() => { try { writeState(state); setSaveError(false); setSaveStatus("Sačuvano lokalno"); if (cloudId) void saveCloud(cloudId, state, cloudVersion).then(setCloudVersion).catch(e => notify(e.message)); } catch { notify("Lokalno čuvanje nije dostupno. Proverite podešavanja pregledača."); } }}>{saveStatus}</button> : saveStatus}</span></div></div><div className="schedule-bottom"><span><RiInformationLine size={15} />Kliknite smenu da je uredite ili je prevucite na drugo mesto.</span><Button size="sm" onClick={() => setModal("publish")}><RiCheckLine size={16} />{schedule.status === "published" ? "Raspored je objavljen" : "Objavi raspored"}</Button></div></section>}

      {page === "Pregled" && <div className="dashboard-grid"><section className="panel"><div className="panel-heading"><h2>Tim na smeni</h2><select value={day} onChange={e => setDay(Number(e.target.value))} aria-label="Dan za pregled">{DAY_NAMES.map((d, i) => <option value={i} key={d}>{d}</option>)}</select></div>{w.templates.map(t => <div className="dashboard-shift" key={t.id}><h3>{t.name}<span>{t.start}–{t.end}</span></h3>{schedule.assignments.filter(a => a.day === day && a.templateId === t.id).map(a => { const e = w.employees.find(e => e.id === a.employeeId)!; return <div className="person-row" key={a.id}><Avatar small employee={e} /><strong>{e.name}</strong><span>{a.position}</span></div>; })}</div>)}<Button variant="outline" onClick={() => setPage("Raspored")}>Otvori raspored<RiArrowRightSLine size={16} /></Button></section><section className="panel"><h2>Raspodela sati</h2><p className="muted">Planirano vreme po članu tima</p><div className="hours-chart">{active.map(e => <div key={e.id}><span>{e.name.split(" ")[0]}</span><div><i style={{ width: `${hoursFor(schedule.assignments, e.id, w.templates) / w.rules.maxWeeklyHours * 100}%` }} /></div><strong>{hoursFor(schedule.assignments, e.id, w.templates)} h</strong></div>)}</div></section></div>}

      {page === "Zaposleni" && <section className="panel employee-panel"><div className="panel-heading"><h2>Vaš tim <span className="tag">{w.employees.length}</span></h2><label className="search-field"><RiSearchLine size={16} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Pretraži zaposlene…" aria-label="Pretraži zaposlene" /></label></div><div className="data-table-scroll"><table className="data-table"><thead><tr><th>IME I PREZIME</th><th>POZICIJE</th><th>NEDELJNI FOND</th><th>STATUS</th><th /></tr></thead><tbody>{w.employees.filter(e => e.name.toLowerCase().includes(query.toLowerCase())).map(e => <tr key={e.id}><td><div className="person-row"><Avatar employee={e} /><strong>{e.name}</strong></div></td><td>{e.positions.map(p => <span className="tag" key={p}>{p}</span>)}</td><td>{e.targetHours} h</td><td><span className={`status-badge ${e.active ? "published" : ""}`}><i />{e.active ? "Aktivan" : "Neaktivan"}</span></td><td><Button variant="ghost" size="sm" onClick={() => { setEditEmployee(e); setFormError(""); setModal("employee"); }}>Uredi<RiArrowRightSLine size={15} /></Button></td></tr>)}</tbody></table></div><p className="panel-footnote">Zaposleni se vode kao evidencija i ne moraju da imaju korisnički nalog.</p></section>}

      {page === "Dostupnost" && <section className="panel"><div className="panel-heading"><div><h2>Nedeljna dostupnost</h2><p className="muted">Kliknite na dan da promenite dostupnost. Pravila se ponavljaju svake nedelje.</p></div><span className="tag">Europe/Belgrade</span></div><div className="data-table-scroll"><table className="data-table availability-table"><thead><tr><th>ZAPOSLENI</th>{DAY_NAMES.map(d => <th key={d}>{d.slice(0, 3).toUpperCase()}</th>)}</tr></thead><tbody>{active.map(e => <tr key={e.id}><td><div className="person-row"><Avatar small employee={e} /><strong>{e.name}</strong></div></td>{DAY_NAMES.map((d, i) => <td key={i}><button className={`availability-button ${e.daysOff.includes(i) ? "unavailable" : ""}`} aria-label={`${e.name}, ${d}: ${e.daysOff.includes(i) ? "nedostupan" : "dostupan"}`} aria-pressed={!e.daysOff.includes(i)} onClick={() => { commit({ ...w, employees: w.employees.map(person => person.id === e.id ? { ...person, daysOff: person.daysOff.includes(i) ? person.daysOff.filter(d => d !== i) : [...person.daysOff, i] } : person) }, `Dostupnost: ${e.name}, ${d}`); }}>{e.daysOff.includes(i) ? <RiCloseLine size={16} /> : <RiCheckLine size={16} />}<span>{e.daysOff.includes(i) ? "Slobodan" : "Dostupan"}</span></button></td>)}</tr>)}</tbody></table></div></section>}

      {page === "Pravila rada" && <div className="settings-grid"><section className="panel"><h2>Pravila raspoređivanja</h2><p className="muted">Zabrane blokiraju raspoređivanje. Upozorenja dozvoljavaju izmenu uz objašnjenje.</p><form className="settings-form" onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); commit({ ...w, rules: { minRestHours: Number(f.get("rest")), maxWeeklyHours: Number(f.get("hours")), restSeverity: f.get("restSeverity") as "warning" | "block", hoursSeverity: f.get("hoursSeverity") as "warning" | "block", allowMultiple: f.get("multiple") === "on" } }, "Izmenjena pravila rada"); notify("Pravila su sačuvana. Proverite postojeći raspored ili generišite novi."); }}><div className="rule-field"><label>Minimalni odmor između smena<div className="input-unit"><input name="rest" type="number" min="0" max="48" defaultValue={w.rules.minRestHours} required /><span>sati</span></div></label><label>Pravilo<select name="restSeverity" defaultValue={w.rules.restSeverity}><option value="block">Zabrana</option><option value="warning">Upozorenje</option></select></label></div><div className="rule-field"><label>Maksimalni nedeljni fond<div className="input-unit"><input name="hours" type="number" min="8" max="168" step="1" defaultValue={w.rules.maxWeeklyHours} required /><span>sati</span></div></label><label>Pravilo<select name="hoursSeverity" defaultValue={w.rules.hoursSeverity}><option value="block">Zabrana</option><option value="warning">Upozorenje</option></select></label></div><label className="check-row"><input type="checkbox" name="multiple" defaultChecked={w.rules.allowMultiple} /><span>Dozvoli više smena dnevno<small>Preklapanje termina je uvek zabranjeno.</small></span></label><Button type="submit">Sačuvaj pravila</Button></form></section><section className="panel"><h2>Potreban broj ljudi</h2><p className="muted">Podesite broj zaposlenih po danu, smeni i poziciji.</p><div className="requirements-editor">{DAY_NAMES.map((name, dayIndex) => <details key={name} open={dayIndex === 0}><summary>{name}<RiArrowDownSLine size={16} /></summary>{w.templates.map(t => <div key={t.id} className="requirement-row"><strong>{t.name}<small>{t.start}–{t.end}</small></strong>{(["Barista", "Konobar"] as Position[]).map(p => <label key={p}>{p}<input type="number" min="0" max="20" aria-label={`${name}, ${t.name}, ${p}`} value={w.requirements.find(r => r.day === dayIndex && r.templateId === t.id && r.position === p)?.count ?? 0} onChange={e => { const count = Math.max(0, Math.min(20, Number(e.target.value))); const rest = w.requirements.filter(r => !(r.day === dayIndex && r.templateId === t.id && r.position === p)); commit({ ...w, requirements: [...rest, { day: dayIndex, templateId: t.id, position: p, count }] }, "Promenjene potrebe tima"); }} /></label>)}</div>)}</details>)}</div></section></div>}

      {page === "Istorija izmena" && <section className="panel"><div className="panel-heading"><h2>Sačuvane promene <span className="tag">{state.past.length}</span></h2><div className="heading-actions"><Button variant="outline" disabled={!state.past.length} onClick={undo}><RiArrowGoBackLine size={16} />Poništi</Button><Button variant="outline" disabled={!state.future.length} onClick={redo}><RiArrowGoForwardLine size={16} />Ponovi</Button></div></div>{!state.past.length ? <Empty>Vaše izmene će se pojaviti ovde. Istorija ostaje sačuvana i posle zatvaranja pregledača.</Empty> : <div className="history-list">{[...state.past].reverse().map((entry, i) => <div key={i}><span className="history-icon"><RiHistoryLine size={17} /></span><span><strong>{entry.label}</strong><small>{new Date(entry.time).toLocaleString("sr-Latn-RS", { timeZone: "Europe/Belgrade", dateStyle: "medium", timeStyle: "short" })}</small></span>{i === 0 && <span className="tag">Poslednja izmena</span>}</div>)}</div>}</section>}

      {page === "Podešavanja" && <div className="settings-grid"><section className="panel"><h2>Vaš kafić</h2><form className="settings-form" onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); commit({ ...w, name: String(f.get("name")).trim() }, "Promenjen naziv kafića"); notify("Podešavanja su sačuvana."); }}><label>Naziv kafića<input name="name" required maxLength={80} defaultValue={w.name} /></label><label>Vremenska zona<input value="Europe/Belgrade" readOnly /></label><label>Izgled<select value={theme} onChange={e => { setTheme(e.target.value); localStorage.setItem("shiftflow:theme", e.target.value); }}><option value="dark">Tamna tema</option><option value="light">Svetla tema</option></select></label><Button type="submit">Sačuvaj podešavanja</Button></form></section><section className="panel"><h2>Vremena smena</h2><p className="muted">Kraj pre početka označava smenu koja prelazi ponoć.</p><form className="settings-form" onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); const templates = w.templates.map(t => ({ ...t, name: String(f.get(`${t.id}-name`)), start: String(f.get(`${t.id}-start`)), end: String(f.get(`${t.id}-end`)) })); if (templates.some(t => t.start === t.end)) { notify("Početak i kraj smene moraju da se razlikuju."); return; } commit({ ...w, templates }, "Promenjena vremena smena"); notify("Vremena smena su sačuvana."); }}>{w.templates.map(t => <div className="template-editor" key={t.id}><label>Naziv<input name={`${t.id}-name`} defaultValue={t.name} required /></label><div className="form-columns"><label>Početak<input name={`${t.id}-start`} type="time" defaultValue={t.start} required /></label><label>Kraj<input name={`${t.id}-end`} type="time" defaultValue={t.end} required /></label></div></div>)}<Button type="submit">Sačuvaj smene</Button></form></section><section className="panel connection-panel"><span className="connection-icon"><RiLockLine size={24} /></span><div><h2>{cloudId ? "Poslovni prostor je povezan" : "Povežite poslovni prostor"}</h2><p className="muted">{cloudId ? "Podaci i istorija se čuvaju u Supabase bazi uz odvojeni pristup za svaku firmu." : "Demo se čuva u ovom pregledaču. Supabase omogućava naloge, zajednički rad i privatne linkove za tim."}</p></div><Button variant="outline" onClick={() => { setModal("auth"); setFormError(""); }}>{cloudId ? "Moj nalog" : "Prijava i registracija"}<RiArrowRightSLine size={16} /></Button></section></div>}

      <footer className="main-footer"><span>ShiftFlow <i>·</i> Dobar raspored pravi razliku.</span><span>Europe/Belgrade <i>·</i> {cloudId ? "Poslovni prostor" : "Demo verzija"}</span></footer>
      </main></div>

    {modal === "generate" && <ModalFrame title="Nova nedelja, dobar plan." description="ShiftFlow usklađuje potrebe kafića sa dostupnošću i pravilima vašeg tima." close={() => !busy && setModal(null)}><div className="generation-visual"><RiSparkling2Line size={29} /><span>Vaš tim. Pametno raspoređen.</span><div><span>{active.length} zaposlenih</span><span>7 dana</span><span>{required} mesta</span></div></div><div className="generation-checklist"><p><RiCheckLine size={16} />Dostupnost i pozicije zaposlenih</p><p><RiCheckLine size={16} />Fond sati i minimum {w.rules.minRestHours} h odmora</p><p><RiCheckLine size={16} />Ravnomernija raspodela sati i vikenda</p></div><label className="check-row"><input type="checkbox" checked={keepLocked} onChange={e => setKeepLocked(e.target.checked)} /><span>Zadrži zaključane smene<small>{schedule.assignments.filter(a => a.locked).length} zaključanih smena u ovom rasporedu</small></span><RiLockLine size={17} /></label>{schedule.assignments.length > 0 && <p className="muted text-small">Otključane smene biće zamenjene novim nacrtom. Promenu možete poništiti.</p>}<div className="modal-actions"><Button variant="outline" disabled={busy} onClick={() => setModal(null)}>Otkaži</Button><Button disabled={busy || !active.length} onClick={() => { setBusy(true); setTimeout(() => { try { const generated = generateSchedule(w, week, keepLocked); updateSchedule(generated, "Automatski generisan raspored"); setModal(null); setPage("Raspored"); const gaps = missingRequirements(generated.assignments, w.requirements).reduce((n, r) => n + r.missing, 0); notify(gaps ? `Nacrt je spreman. Preostalo je ${gaps} nepopunjenih mesta.` : "Raspored je spreman. Sve smene su popunjene."); } finally { setBusy(false); } }, 100); }}><RiSparkling2Line size={16} />{busy ? "Pravimo vaš raspored…" : "Generiši raspored"}</Button></div></ModalFrame>}

    {modal === "employee" && <ModalFrame title={editEmployee ? "Uredi zaposlenog" : "Novi član tima"} description="Dodajte osnovne podatke i pozicije za raspoređivanje." close={() => setModal(null)}><form className="dialog-form" onSubmit={saveEmployee}><label>Ime i prezime<input name="name" autoFocus required minLength={2} maxLength={80} defaultValue={editEmployee?.name} placeholder="npr. Ana Petrović" /></label><fieldset><legend>Pozicije</legend><div className="position-options">{positions.map(p => <label key={p}><input type="checkbox" name="positions" value={p} defaultChecked={editEmployee?.positions.includes(p)} />{p}</label>)}</div></fieldset><div className="form-columns"><label>Nedeljni fond sati<input type="number" name="hours" min="8" max="80" step="1" defaultValue={editEmployee?.targetHours ?? 40} required /></label><label>Željena smena<select name="preferred" defaultValue={editEmployee?.preferredShift ?? ""}><option value="">Bez preference</option>{w.templates.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select></label></div><label className="check-row"><input type="checkbox" name="active" defaultChecked={editEmployee?.active ?? true} /><span>Aktivan član tima<small>Neaktivni zaposleni ne ulaze u automatsko generisanje.</small></span></label>{formError && <p className="form-error" role="alert">{formError}</p>}<div className="modal-actions"><Button type="button" variant="outline" onClick={() => setModal(null)}>Otkaži</Button><Button type="submit">Sačuvaj zaposlenog</Button></div></form></ModalFrame>}

    {modal === "shift" && editShift && <ModalFrame title={editShift.id ? "Uredi smenu" : "Dodaj smenu"} description="Brza promena, uz automatsku proveru pravila." close={() => setModal(null)}><form className="dialog-form" onSubmit={saveShift}><label>Zaposleni<select name="employeeId" value={editShift.employeeId} onChange={e => setEditShift(s => ({ ...s, employeeId: e.target.value, position: w.employees.find(p => p.id === e.target.value)?.positions[0] }))}>{active.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></label><div className="form-columns"><label>Dan<select name="day" defaultValue={editShift.day}>{DAY_NAMES.map((name, i) => <option key={name} value={i}>{name}</option>)}</select></label><label>Smena<select name="templateId" defaultValue={editShift.templateId}>{w.templates.map(t => <option key={t.id} value={t.id}>{t.name} · {t.start}–{t.end}</option>)}</select></label></div><label>Pozicija<select name="position" key={editShift.employeeId} defaultValue={editShift.position}>{(w.employees.find(e => e.id === editShift.employeeId)?.positions ?? positions).map(p => <option key={p}>{p}</option>)}</select></label><label>Interna napomena<textarea name="note" rows={2} maxLength={500} defaultValue={editShift.note} placeholder="Vidljiva samo menadžerima…" /></label><label className="check-row"><input type="checkbox" name="locked" defaultChecked={editShift.locked} /><span>Zaključaj smenu<small>Ostaje sačuvana prilikom ponovnog generisanja.</small></span><RiLockLine size={17} /></label>{formError && <p className="form-error" role="alert">{formError}</p>}<div className="modal-actions">{editShift.id && <button type="button" className="delete-button" onClick={() => { updateSchedule({ ...schedule, assignments: schedule.assignments.filter(a => a.id !== editShift.id) }, "Obrisana smena"); setModal(null); }}><RiDeleteBinLine size={16} />Obriši</button>}<Button type="button" variant="outline" onClick={() => setModal(null)}>Otkaži</Button><Button type="submit">Sačuvaj smenu</Button></div></form></ModalFrame>}

    {modal === "publish" && <ModalFrame title={schedule.status === "published" ? "Raspored je objavljen" : "Spremni za novu nedelju?"} description="Pregledajte raspored pre nego što ga podelite sa timom." close={() => setModal(null)}><div className="publish-summary"><RiCalendar2Line size={30} /><h3>{dates[0].getUTCDate()}–{dates[6].getUTCDate()}. {dateLabel(dates[6], { month: "long", year: "numeric" })}</h3><p>{active.length} zaposlenih · {schedule.assignments.length} smena · {totalHours} sati</p></div>{blockers.length || missingCount ? <div className="form-error"><strong>Još malo do gotovog rasporeda.</strong><p>{missingCount} nepopunjenih mesta i {blockers.length} kršenja pravila. Otvorite proveru rasporeda da vidite detalje.</p><Button variant="outline" onClick={() => { setShowProblems(true); setModal(null); }}>Pregledaj probleme</Button></div> : <p className="success-text"><RiCheckLine size={17} />Sve smene su popunjene i nema blokirajućih konflikata.</p>}<p className="muted text-small">{cloudId ? "Naknadne izmene automatski ažuriraju objavljeni pregled." : "U demo režimu objavljivanje označava status lokalnog rasporeda. Za privatni link povežite Supabase."}</p><div className="modal-actions"><Button variant="outline" onClick={() => setModal(null)}>Zatvori</Button><Button disabled={!!blockers.length || !!missingCount} onClick={() => { updateSchedule({ ...schedule, status: "published", publishedAt: new Date().toISOString() }, "Objavljen raspored"); setModal(null); notify(cloudId ? "Raspored je objavljen. Sada možete napraviti privatni link." : "Demo raspored je označen kao objavljen."); }}><RiCheckLine size={16} />Objavi raspored</Button></div></ModalFrame>}

    {modal === "share" && <ModalFrame title="Podelite dobar plan." description="Zaposleni vide samo objavljene smene, imena i pozicije. Interne napomene ostaju privatne." close={() => setModal(null)}>{!cloudId ? <div className="share-notice"><RiShareForwardLine size={31} /><h3>Privatni link zahteva povezanu bazu</h3><p>Trenutno koristite demo sa podacima u ovom pregledaču. Raspored možete preuzeti kao sliku ili PDF, a za link se prijavite u povezani poslovni prostor.</p><Button onClick={() => { setModal("export"); }}>Preuzmi raspored<RiDownloadLine size={16} /></Button></div> : schedule.status !== "published" ? <div className="share-notice"><RiInformationLine size={28} /><h3>Prvo objavite raspored</h3><p>Tim vidi samo objavljen raspored.</p><Button onClick={() => setModal("publish")}>Pregledaj i objavi</Button></div> : <div className="dialog-form"><label>Privatni link<input readOnly value={shareUrl} placeholder="Generišite link za ovaj raspored" /></label><Button disabled={busy} onClick={async () => { setBusy(true); try { const url = await createShare(cloudId, week); setShareUrl(url); notify("Novi link je spreman. Prethodni link je opozvan."); } catch (e) { notify((e as Error).message); } finally { setBusy(false); } }}><RiRefreshLine size={16} />{shareUrl ? "Opozovi i generiši novi link" : "Generiši privatni link"}</Button>{shareUrl && <Button variant="outline" onClick={() => { void navigator.clipboard.writeText(shareUrl).then(() => notify("Link je kopiran.")).catch(() => notify("Označite i kopirajte link iz polja.")); }}>Kopiraj link</Button>}</div>}</ModalFrame>}

    {modal === "export" && <ModalFrame title="Raspored, spreman za tim." description="Izaberite format za preuzimanje. Interne napomene se ne prikazuju u izvozu." close={() => setModal(null)}><div className="export-options"><button disabled={busy} onClick={() => { setModal(null); setView("week"); setQuery(""); setPosition("all"); setTimeout(() => window.print(), 200); }}><RiCalendar2Line size={25} /><strong>PDF dokument</strong><span>Otvori štampu → Sačuvaj kao PDF</span><RiArrowRightUpLine size={18} /></button><button disabled={busy} onClick={() => { setView("week"); setQuery(""); setPosition("all"); setTimeout(() => void exportImage(), 150); }}><RiDownloadLine size={25} /><strong>{busy ? "Pripremamo sliku…" : "PNG slika"}</strong><span>Jasna slika za grupni razgovor</span><RiArrowRightUpLine size={18} /></button></div></ModalFrame>}

    {modal === "auth" && <ModalFrame title={cloudId ? "Vaš nalog" : "Dobro došli u ShiftFlow."} description={cloudId ? authUser : "Prijavite se ili otvorite poslovni prostor za svoj tim."} close={() => setModal(null)}>{cloudId ? <div className="dialog-form"><p className="success-text"><RiLockLine size={17} />Povezano sa firmom {w.name}.</p><Button variant="outline" onClick={async () => { await getSupabase()?.auth.signOut(); location.reload(); }}><RiLogoutBoxRLine size={16} />Odjavi se</Button></div> : !getSupabase() ? <div className="share-notice"><RiLockLine size={28} /><h3>Demo je spreman za isprobavanje</h3><p>Registracija i prijava biće dostupne kada se poveže Supabase projekat. Vaš demo raspored se trenutno čuva lokalno.</p><Button onClick={() => setModal(null)}>Nastavi u demo prostoru</Button></div> : <form className="dialog-form" onSubmit={async e => { e.preventDefault(); const f = new FormData(e.currentTarget); const submitter = (e.nativeEvent as SubmitEvent).submitter as HTMLButtonElement; const signup = submitter?.value === "signup"; setBusy(true); setFormError(""); try { const db = getSupabase()!; const email = String(f.get("email")); const password = String(f.get("password")); const result = signup ? await db.auth.signUp({ email, password, options: { data: { company_name: String(f.get("company")) } } }) : await db.auth.signInWithPassword({ email, password }); if (result.error) throw result.error; if (signup && !result.data.session) { notify("Proverite email da potvrdite registraciju, pa se prijavite."); setModal(null); } else { const cloud = await loadCloud(); if (cloud) { setCloudId(cloud.company_id); setCloudVersion(cloud.version); cloudRevision.current = cloud.state.revision; setState(cloud.state); } setAuthUser(email); setModal(null); notify("Uspešno ste prijavljeni."); } } catch (err) { setFormError((err as Error).message); } finally { setBusy(false); } }}><label>Email<input type="email" name="email" autoComplete="email" required /></label><label>Lozinka<input type="password" name="password" minLength={8} autoComplete="current-password" required /></label><label>Naziv firme <span className="muted">(za registraciju)</span><input name="company" placeholder="Moj kafić" maxLength={80} /></label>{formError && <p className="form-error">{formError}</p>}<Button disabled={busy} type="submit" value="signin">Prijavi se</Button><Button disabled={busy} variant="outline" type="submit" value="signup">Registruj firmu</Button></form>}</ModalFrame>}

    {modal === "notifications" && <ModalFrame title="Obaveštenja" description="Sve što je važno za vaš tim." close={() => setModal(null)}><div className="notification-item"><span className="note-icon"><RiCheckboxCircleLine size={20} /></span><div><strong>{schedule.status === "published" ? "Raspored je objavljen" : "Vaš raspored je u pripremi"}</strong><p>{schedule.assignments.length} smena u nedelji od {week}.</p></div></div><div className="notification-item"><span className="note-icon"><RiInformationLine size={20} /></span><div><strong>{missingCount ? `${missingCount} mesta čeka na popunjavanje` : "Sve smene su popunjene"}</strong><p>{conflicts.length ? `Proverite ${conflicts.length} upozorenja u rasporedu.` : "Provera pravila rada je završena."}</p></div></div></ModalFrame>}
    {toast && <div className="toast" role="status"><RiCheckboxCircleLine size={19} /><span>{toast}</span><button className="icon-button" aria-label="Zatvori obaveštenje" onClick={() => setToast("")}><RiCloseLine size={16} /></button></div>}
  </div>;
}
